// Stamp updatedAt on an item whenever it's modified
// ── Field-level timestamps (lightweight CRDT) ────────────
// touchField stamps individual fields in item._fieldTs so mergeItems
// can resolve conflicts at field granularity rather than whole-item LWW.
// Fields with no _fieldTs entry fall back to item-level updatedAt.
function touchField(item, ...fields) {
  const now = new Date().toISOString();
  item.updatedAt = now;
  if (!item._fieldTs) item._fieldTs = {};
  if (fields.length === 0) {
    // No specific fields — stamp the whole item (backwards compat for touchItem callers)
    return;
  }
  fields.forEach(f => { item._fieldTs[f] = now; });
}

// Keep touchItem as an alias for callers that set multiple fields at once
function touchItem(item) { touchField(item); }

// ── Logs union merge ─────────────────────────────────────
// Logs are append-only — merge by ID union, never discard an entry
function mergeLogs(localLogs = [], remoteLogs = []) {
  const byId = new Map();
  // Remote first so local can overwrite (local edits to existing logs win)
  for (const l of remoteLogs) byId.set(l.id, l);
  for (const l of localLogs)  byId.set(l.id, l);
  return Array.from(byId.values()).sort((a, b) => new Date(a.date) - new Date(b.date));
}

// ── Field-level item merge ───────────────────────────────
function mergeItemFields(local, remote) {
  // Start with a shallow copy of local
  const result = { ...local };

  // Fields we track individually — everything except id, updatedAt, _fieldTs, logs
  const SCALAR_FIELDS = [
    'name','category','cadence','qty','months','daysPerUnit','url','store','notes',
    'startedUsing','rating','imageUrl','storePrices','expiry',
    'thresholdOverride','replacementInterval','replacementUnit',
    'lastReplaced','ordered','orderedAt','quickAdded','tags',
    'subscribeAndSave','stockCount','stockCountDate',
  ];

  const localTs  = local._fieldTs  || {};
  const remoteTs = remote._fieldTs || {};
  const itemLocalTime  = local.updatedAt  ? new Date(local.updatedAt).getTime()  : 0;
  const itemRemoteTime = remote.updatedAt ? new Date(remote.updatedAt).getTime() : 0;

  for (const field of SCALAR_FIELDS) {
    if (!(field in remote)) continue; // remote doesn't have this field — keep local
    const lt = localTs[field]  ? new Date(localTs[field]).getTime()  : itemLocalTime;
    const rt = remoteTs[field] ? new Date(remoteTs[field]).getTime() : itemRemoteTime;
    if (rt > lt) result[field] = remote[field];
  }

  // Logs: union merge by ID
  result.logs = mergeLogs(local.logs, remote.logs);

  // Merge _fieldTs — keep the newest timestamp per field
  result._fieldTs = { ...remoteTs, ...localTs };
  for (const f of Object.keys(remoteTs)) {
    if (!localTs[f] || new Date(remoteTs[f]) > new Date(localTs[f])) {
      result._fieldTs[f] = remoteTs[f];
    }
  }

  // updatedAt = newest of the two
  result.updatedAt = itemLocalTime >= itemRemoteTime ? local.updatedAt : remote.updatedAt;

  return result;
}

async function mergeItems(local, remote, remoteWins = false) {
  const deletedIds = await loadDeletedIds();
  const merged = new Map();

  for (const item of local) {
    if (!deletedIds.has(item.id)) merged.set(item.id, item);
  }

  for (const remoteItem of remote) {
    if (deletedIds.has(remoteItem.id)) continue;
    const localItem = merged.get(remoteItem.id);
    if (!localItem) {
      // Item only in remote — add it
      merged.set(remoteItem.id, remoteItem);
    } else {
      // Item in both — field-level merge
      merged.set(remoteItem.id, mergeItemFields(localItem, remoteItem));
    }
  }

  return Array.from(merged.values());
}
// ── Grocery tombstones — tracks deleted grocery item IDs so they aren't re-added on sync
async function loadGroceryDeletedIds() {
  try {
    const stored = await dbGet('groceryDeletedIds', 'groceryDeletedIds');
    return new Set(Array.isArray(stored) ? stored : []);
  } catch(e) { return new Set(); }
}
async function addGroceryTombstone(id) {
  try {
    const set = await loadGroceryDeletedIds();
    set.add(id);
    // Keep max 500 tombstones; prune oldest if over limit
    const arr = [...set];
    const trimmed = arr.slice(-500);
    await dbPut('groceryDeletedIds', 'groceryDeletedIds', trimmed);
  } catch(e) {}
}

// ── Reminder tombstones — tracks deleted standalone reminder IDs so they
// aren't re-added on next sync (item-linked reminders are tracked via the
// item's own replacementReminders array and don't need this).
async function loadReminderDeletedIds() {
  try {
    const stored = await dbGet('reminderDeletedIds', 'reminderDeletedIds');
    return new Set(Array.isArray(stored) ? stored : []);
  } catch(e) { return new Set(); }
}
async function addReminderTombstone(id) {
  try {
    const set = await loadReminderDeletedIds();
    set.add(id);
    const arr = [...set];
    const trimmed = arr.slice(-500);
    await dbPut('reminderDeletedIds', 'reminderDeletedIds', trimmed);
  } catch(e) {}
}

// ── Grocery list tombstones ──────────────────────────────────────────
// Without these, deleting a list locally hard-removes it but the next
// pull restores it from the remote payload (the items get filtered by
// item-level _deletedAt, but the list itself has no tombstone).
async function loadGroceryListDeletedIds() {
  try {
    const stored = await dbGet('groceryLists', '_deletedIds');
    return new Set(Array.isArray(stored) ? stored : []);
  } catch(e) { return new Set(); }
}
async function addGroceryListTombstone(id) {
  try {
    const set = await loadGroceryListDeletedIds();
    set.add(id);
    const arr = [...set].slice(-500);
    await dbPut('groceryLists', '_deletedIds', arr);
  } catch(e) {}
}

async function loadDeletedIds() {
  const stored = await dbGet('deletedIds', 'deletedIds');
  if (stored) return new Set(stored);
  // Migration from localStorage
  try {
    const raw = localStorage.getItem('stockroom_deleted_ids');
    if (raw) {
      const set = new Set(JSON.parse(raw));
      await saveDeletedIds(set);
      localStorage.removeItem('stockroom_deleted_ids');
      return set;
    }
  } catch(e) {}
  return new Set();
}
async function saveDeletedIds(set) {
  await dbPut('deletedIds', 'deletedIds', [...set]);
}
async function addTombstone(id) {
  const set = await loadDeletedIds();
  set.add(id);
  await saveDeletedIds(set);
}
async function removeTombstone(id) {
  const set = await loadDeletedIds();
  set.delete(id);
  await saveDeletedIds(set);
}

// ═══════════════════════════════════════════
//  RECYCLE BIN — soft-delete helpers
// ═══════════════════════════════════════════
// Items, grocery items, and standalone reminders use _deletedAt as the
// soft-delete marker. After 30 days a one-time purge sweep at app start
// hard-removes them and writes a tombstone (so sync can't resurrect them).

const RECYCLE_BIN_DAYS = 30;
const RECYCLE_BIN_MS   = RECYCLE_BIN_DAYS * 24 * 60 * 60 * 1000;

function _isInRecycleBin(obj) {
  return !!(obj && obj._deletedAt);
}

function _daysLeftInBin(obj) {
  if (!obj?._deletedAt) return null;
  const elapsed = Date.now() - new Date(obj._deletedAt).getTime();
  return Math.max(0, RECYCLE_BIN_DAYS - Math.floor(elapsed / 86400000));
}

function _expiredFromBin(obj) {
  if (!obj?._deletedAt) return false;
  return (Date.now() - new Date(obj._deletedAt).getTime()) >= RECYCLE_BIN_MS;
}

// One-time hint after first soft-delete in each section, so users know
// where deleted things go. Stored in localStorage so it persists.
function _maybeShowBinHint(section) {
  const key = `stockroom_bin_hint_${section}`;
  if (localStorage.getItem(key)) return;
  localStorage.setItem(key, '1');
  const where = {
    items: 'the bottom of the Stockroom view',
    groceries: 'the bottom of the Groceries view',
    reminders: 'the bottom of the Reminders view',
  }[section] || 'the Recently Deleted section';
  toast(`Tip: deleted things sit in ${where} for 30 days`);
}

// Preserve local soft-deletes when applying a wholesale remote replacement.
// The grocery / reminders sync code paths replace the whole array with the
// remote on `remoteWins`, but the user may have just soft-deleted items
// that haven't been pushed yet. This merges the remote list with any local
// `_deletedAt` markers so freshly deleted items don't resurrect on pull.
//
// Returns a new array of items derived from `remote`, with `_deletedAt`
// (and updatedAt) carried over from any matching local item that was in
// the recycle bin.
function _preserveLocalDeletes(remote, local) {
  if (!Array.isArray(remote)) return remote;
  if (!Array.isArray(local) || !local.length) return remote;
  const localDeleted = new Map();
  for (const it of local) {
    if (it && it._deletedAt) {
      // Keep the more recent updatedAt of the two (local edit wins)
      localDeleted.set(it.id, { _deletedAt: it._deletedAt, updatedAt: it.updatedAt });
    }
  }
  if (!localDeleted.size) return remote;
  return remote.map(it => {
    const ld = localDeleted.get(it?.id);
    if (!ld) return it;
    // Preserve local soft-delete; keep the later updatedAt so subsequent
    // sync rounds don't resurrect by stale-timestamp.
    const localUpd = ld.updatedAt ? new Date(ld.updatedAt).getTime() : 0;
    const remUpd   = it.updatedAt ? new Date(it.updatedAt).getTime() : 0;
    return { ...it, _deletedAt: ld._deletedAt, updatedAt: localUpd >= remUpd ? ld.updatedAt : it.updatedAt };
  });
}

async function purgeExpiredFromBins() {
  // Purges items, grocery items, and standalone reminders whose 30-day
  // recycle bin window has expired. Writes tombstones so sync doesn't
  // resurrect them. Runs once at app start.
  let dirtyItems = false, dirtyGrocery = false, dirtyReminders = false;

  if (Array.isArray(items)) {
    const expired = items.filter(_expiredFromBin);
    if (expired.length) {
      for (const it of expired) await addTombstone(it.id);
      items = items.filter(i => !_expiredFromBin(i));
      dirtyItems = true;
    }
  }

  if (Array.isArray(groceryItems)) {
    const expired = groceryItems.filter(_expiredFromBin);
    if (expired.length) {
      for (const g of expired) await addGroceryTombstone(g.id);
      groceryItems = groceryItems.filter(i => !_expiredFromBin(i));
      dirtyGrocery = true;
    }
  }

  if (Array.isArray(reminders)) {
    const expired = reminders.filter(_expiredFromBin);
    if (expired.length) {
      for (const r of expired) await addReminderTombstone(r.id);
      reminders = reminders.filter(r => !_expiredFromBin(r));
      dirtyReminders = true;
    }
  }

  try {
    if (dirtyItems)     await saveData();
    if (dirtyGrocery)   await saveGrocery();
    if (dirtyReminders) await saveReminders();
  } catch(e) { console.warn('purgeExpiredFromBins save failed:', e); }
}

async function mergeItems(local, remote, remoteWins = false) {
  const deletedIds = await loadDeletedIds();
  const merged = new Map();
  for (const item of local) {
    if (!deletedIds.has(item.id)) merged.set(item.id, item);
  }
  for (const remoteItem of remote) {
    if (deletedIds.has(remoteItem.id)) continue;
    const localItem = merged.get(remoteItem.id);
    if (!localItem) {
      merged.set(remoteItem.id, remoteItem);
    } else {
      const localTime  = localItem.updatedAt  ? new Date(localItem.updatedAt).getTime()  : null;
      const remoteTime = remoteItem.updatedAt ? new Date(remoteItem.updatedAt).getTime() : null;
      if (localTime !== null && remoteTime !== null) {
        if (remoteTime > localTime) merged.set(remoteItem.id, remoteItem);
      } else if (remoteTime !== null && localTime === null) {
        merged.set(remoteItem.id, remoteItem);
      } else if (localTime !== null && remoteTime === null) {
        // local wins
      } else {
        if (remoteWins) merged.set(remoteItem.id, remoteItem);
      }
    }
  }
  return Array.from(merged.values());
}

